class EventTicket { protected String attendeeId; protected double basePrice,balanceDue; EventTicket(String id,double price){if(id==null||id.trim().length()<4||price<=0)throw new IllegalArgumentException();attendeeId=id;basePrice=price;balanceDue=price;} void pay(double amount){if(amount>0)balanceDue=Math.max(0,balanceDue-amount);} double getBalanceDue(){return balanceDue;} }
class WorkshopTicket extends EventTicket{String track;WorkshopTicket(String id,double price,String track){super(id,price);this.track=track;}}
public class Problem1{static String registerBatch(String[] ids,double price){int ok=0,bad=0;for(String id:ids){try{new EventTicket(id,price);ok++;}catch(IllegalArgumentException e){bad++;}}return "Registered: "+ok+" | Rejected: "+bad;}public static void main(String[]x){System.out.println(registerBatch(new String[]{"STU1","ST1","STU2"," ","STU3"},580));}}
